CREATE TYPE "Role" AS ENUM ('ADMIN','AGENT','USER'); CREATE TYPE "TransactionType" AS ENUM ('MINT','TRANSFER','REDEEM'); CREATE TYPE "AccountType" AS ENUM ('WALLET','SANDBOX_RESERVE');
CREATE TABLE "User"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Wallet"("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"balance" BIGINT NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LedgerTransaction"("id" TEXT PRIMARY KEY,"type" "TransactionType" NOT NULL,"amount" BIGINT NOT NULL,"reference" TEXT NOT NULL UNIQUE,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LedgerEntry"("id" TEXT PRIMARY KEY,"transactionId" TEXT NOT NULL,"walletId" TEXT,"accountType" "AccountType" NOT NULL,"amount" BIGINT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog"("id" TEXT PRIMARY KEY,"userId" TEXT,"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SystemState"("id" INTEGER PRIMARY KEY,"reserveCap" BIGINT NOT NULL,"mintedTotal" BIGINT NOT NULL DEFAULT 0,"redeemedTotal" BIGINT NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL);
ALTER TABLE "Wallet" ADD CONSTRAINT "Wallet_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id"); ALTER TABLE "LedgerEntry" ADD CONSTRAINT "LedgerEntry_transactionId_fkey" FOREIGN KEY("transactionId") REFERENCES "LedgerTransaction"("id"); ALTER TABLE "LedgerEntry" ADD CONSTRAINT "LedgerEntry_walletId_fkey" FOREIGN KEY("walletId") REFERENCES "Wallet"("id"); ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id");
